</script>
<ol bind:this={root} class="rx-timeline rx-timeline--{variant} rx-timeline--{orientation}" class:is-flow={flow} class:is-pulse={pulse} class:is-reveal={reveal} data-size={size} data-align={variant==='alternating'?'alternate':align} data-line={lineStyle} style={styleColor(color)??'--rx-color:var(--rx-primary)'} {@attach attach}>
